INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("アヤネ", 24, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 0, 24001, 0, 2, "2030/12/17 14:59:59", 0, 2, 401, "2020/07/31 12:00:00", 10046, 102301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("アヤネ", 24, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 0, 24002, 2.21, 2, "2030/12/17 14:59:59", 0, 1, 402, "2020/07/31 12:00:00", 10046, 102301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("アヤネ", 24, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 0, 24003, 0, 2, "2030/12/17 14:59:59", 0, 2, 403, "2020/07/31 12:00:00", 10046, 102301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("アサヒ", 24, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 0, 24004, 1.99, 1, "2030/12/17 14:59:59", 0, 2, 701, "2020/07/31 12:00:00", 10046, 192201);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("アサヒ", 24, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 0, 24005, 2.21, 2, "2030/12/17 14:59:59", 0, 1, 702, "2020/07/31 12:00:00", 10046, 192201);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("アサヒ", 24, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 0, 24006, 3.33, 1, "2030/12/17 14:59:59", 0, 2, 703, "2020/07/31 12:00:00", 10046, 192201);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("部員３", 24, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 0, 24007, 0, 2, "2030/12/17 14:59:59", 0, 2, 801, "2020/07/31 12:00:00", 10046, 192301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("部員３", 24, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 0, 24008, 2.68, 2, "2030/12/17 14:59:59", 0, 1, 802, "2020/07/31 12:00:00", 10046, 192301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("部員３", 24, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 0, 24009, 0, 2, "2030/12/17 14:59:59", 0, 2, 803, "2020/07/31 12:00:00", 10046, 192301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("", 24, "やった！", 0, 24010, 0, 1, "2030/12/17 14:59:59", 0, 1, 501, "2020/07/31 12:00:00", 10046, 192501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("", 24, "勝ったよ！", 0, 24011, 0, 1, "2030/12/17 14:59:59", 0, 1, 502, "2020/07/31 12:00:00", 10046, 192501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("", 24, "いい調子！", 0, 24012, 0, 1, "2030/12/17 14:59:59", 0, 1, 503, "2020/07/31 12:00:00", 10046, 192501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ミサト", 24, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 0, 24013, 5.33, 2, "2030/12/17 14:59:59", 0, 6, 111, "2020/07/31 12:00:00", 10046, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ミサト", 24, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 0, 24014, 6.85, 2, "2030/12/17 14:59:59", 0, 1, 112, "2020/07/31 12:00:00", 10046, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ミサト", 24, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 0, 24015, 3, 2, "2030/12/17 14:59:59", 0, 1, 113, "2020/07/31 12:00:00", 10046, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ダイチ", 24, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 0, 24016, 6.11, 2, "2030/12/17 14:59:59", 0, 1, 611, "2020/07/31 12:00:00", 10046, 192401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ダイチ", 24, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 0, 24017, 6.75, 2, "2030/12/17 14:59:59", 0, 1, 612, "2020/07/31 12:00:00", 10046, 192401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ダイチ", 24, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 0, 24018, 0, 2, "2030/12/17 14:59:59", 0, 2, 613, "2020/07/31 12:00:00", 10046, 192401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ハツネ", 24, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 0, 24019, 4.52, 1, "2030/12/17 14:59:59", 0, 2, 211, "2020/07/31 12:00:00", 10046, 113401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ハツネ", 24, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 0, 24020, 3.89, 1, "2030/12/17 14:59:59", 0, 2, 212, "2020/07/31 12:00:00", 10046, 113401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ハツネ", 24, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 0, 24021, 13.49, 2, "2030/12/17 14:59:59", 0, 1, 213, "2020/07/31 12:00:00", 10046, 113401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("カヤ", 24, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 0, 24022, 3.17, 2, "2030/12/17 14:59:59", 0, 1, 311, "2020/07/31 12:00:00", 10046, 106501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("カヤ", 24, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 0, 24023, 4.42, 2, "2030/12/17 14:59:59", 0, 1, 312, "2020/07/31 12:00:00", 10046, 106501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("カヤ", 24, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 0, 24024, 2.89, 1, "2030/12/17 14:59:59", 0, 6, 313, "2020/07/31 12:00:00", 10046, 106501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("アヤネ", 24, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 0, 24025, 3.71, 3, "2030/12/17 14:59:59", 0, 4, 421, "2020/07/31 12:00:00", 10046, 102301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("アサヒ", 24, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 0, 24026, 5.1, 1, "2030/12/17 14:59:59", 0, 2, 721, "2020/07/31 12:00:00", 10046, 192201);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("部員３", 24, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 0, 24027, 4.34, 3, "2030/12/17 14:59:59", 0, 1, 821, "2020/07/31 12:00:00", 10046, 192301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("", 24, "いい勝負だったよ\nまたやろうね", 0, 24028, 0, 1, "2030/12/17 14:59:59", 0, 1, 521, "2020/07/31 12:00:00", 10046, 192501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ミサト", 24, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", -360, 24029, 5.62, 2, "2030/12/17 14:59:59", 0, 1, 101, "2020/07/31 12:00:00", 10046, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ミサト", 24, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", -360, 24030, 9.58, 2, "2030/12/17 14:59:59", 0, 1, 102, "2020/07/31 12:00:00", 10046, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ミサト", 24, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", -360, 24031, 0, 2, "2030/12/17 14:59:59", 0, 2, 103, "2020/07/31 12:00:00", 10046, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ミサト", 24, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", -360, 24032, 9.13, 1, "2030/12/17 14:59:59", 0, 2, 104, "2020/07/31 12:00:00", 10046, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ミサト", 24, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", -360, 24033, 8.27, 2, "2030/12/17 14:59:59", 0, 1, 105, "2020/07/31 12:00:00", 10046, 113501);
